        --accent-2: #68e1fd;
        --success: #7ee2a8;
        --danger: #ff7a90;
        --shadow: 0 24px 70px rgba(0, 0, 0, 0.45);
        --radius: 28px;
      }

      * {
        box-sizing: border-box;
      }

      html {
        scroll-behavior: smooth;
      }

      body {
        margin: 0;
        background:
          radial-gradient(circle at top left, rgba(104, 225, 253, 0.18), transparent 34rem),
          radial-gradient(circle at 85% 12%, rgba(244, 184, 96, 0.16), transparent 28rem),
          linear-gradient(135deg, #070910 0%, #0d111b 48%, #090b11 100%);
        color: var(--text);
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
        line-height: 1.5;
      }

      a {
        color: inherit;
        text-decoration: none;
      }

      a:focus-visible,
      button:focus-visible {
        outline: 3px solid var(--accent-2);
        outline-offset: 4px;
      }

      button,
      input {
        font: inherit;
      }

      .page-shell {
        min-height: 100vh;
        overflow: hidden;
      }

      .container {
        width: min(1180px, calc(100% - 32px));
        margin: 0 auto;
      }

      .skip-link {
        position: absolute;
        left: 16px;
        top: 16px;
        z-index: 10;
        transform: translateY(-160%);
        border-radius: 999px;
        background: var(--text);
        color: var(--bg);
        padding: 10px 16px;
        font-weight: 800;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .site-header {
        position: sticky;
        top: 0;
        z-index: 5;
        border-bottom: 1px solid var(--line);
        background: rgba(8, 10, 15, 0.78);
        backdrop-filter: blur(18px);
      }

      .nav {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 24px;
        padding: 18px 0;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 12px;
        font-size: 1.02rem;
        font-weight: 900;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      .brand-mark {
        display: grid;
        width: 42px;
        height: 42px;
        place-items: center;
        border: 1px solid rgba(244, 184, 96, 0.45);
        border-radius: 15px;
        background: linear-gradient(135deg, rgba(244, 184, 96, 0.25), rgba(104, 225, 253, 0.08));
        color: var(--accent);
        box-shadow: 0 10px 30px rgba(244, 184, 96, 0.13);
      }

      .nav-links {
        display: flex;
        align-items: center;
        gap: 24px;
        color: var(--muted);
        font-weight: 700;
      }

      .nav-links a:hover {
        color: var(--text);
      }

      .nav-actions {
        display: flex;
        align-items: center;
        gap: 12px;
      }

      .icon-button {
        display: inline-grid;
        width: 44px;
        height: 44px;
        place-items: center;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.04);
        color: var(--text);
        cursor: pointer;
      }

      .cart-pill {
        display: inline-flex;
        align-items: center;
        gap: 8px;
        border: 1px solid rgba(244, 184, 96, 0.36);
        border-radius: 999px;
        background: rgba(244, 184, 96, 0.1);
        padding: 11px 16px;
        color: var(--text);
        font-weight: 900;
      }

      .hero {
        position: relative;
        display: grid;
        grid-template-columns: minmax(0, 1.08fr) minmax(320px, 0.92fr);
        gap: 34px;
        align-items: center;
        padding: 72px 0 50px;
      }

      .hero-copy,
      .hero-card,
      .product-card,
      .deal-card,
      .story-card,
      .newsletter {
        border: 1px solid var(--line);
        background: var(--panel);
        box-shadow: var(--shadow);
        backdrop-filter: blur(16px);
      }

      .hero-copy {
        position: relative;
        border-radius: var(--radius);
        padding: clamp(32px, 5vw, 58px);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 10px;
        margin: 0 0 18px;
        color: var(--accent);
        font-size: 0.78rem;
        font-weight: 900;
        letter-spacing: 0.18em;
        text-transform: uppercase;
      }

      .eyebrow::before {
        display: inline-block;
        width: 34px;
        height: 2px;
        background: currentColor;
        content: "";
      }

      h1,
      h2,
      h3,
      p {
        margin-top: 0;
      }

      h1 {
        max-width: 790px;
        margin-bottom: 20px;
        font-size: clamp(3rem, 8vw, 6.8rem);
        line-height: 0.9;
        letter-spacing: -0.08em;
      }

      .hero-copy p {
        max-width: 650px;
        color: var(--muted);
        font-size: clamp(1.05rem, 2vw, 1.28rem);
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 14px;
        margin-top: 30px;
      }

      .button {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        min-height: 48px;
        border: 1px solid transparent;
        border-radius: 999px;
        padding: 0 20px;
        font-weight: 900;
      }

      .button-primary {
        background: linear-gradient(135deg, var(--accent), #ffd98a);
        color: #171009;
      }

      .button-secondary {
        border-color: var(--line);
        background: rgba(255, 255, 255, 0.05);
        color: var(--text);
      }

      .hero-stats {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 12px;
        margin-top: 34px;
      }

      .stat {
        border: 1px solid var(--line);
        border-radius: 20px;
        background: rgba(255, 255, 255, 0.04);
        padding: 16px;
      }

      .stat strong {
        display: block;
        color: var(--text);
        font-size: 1.5rem;
        line-height: 1;
      }

      .stat span {
        color: var(--muted);
        font-size: 0.86rem;
      }

      .hero-card {
        border-radius: var(--radius);
        padding: 20px;
      }

      .spotlight {
        min-height: 520px;
        border-radius: 24px;
        background:
          linear-gradient(180deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0.03)),
          radial-gradient(circle at 52% 22%, rgba(104, 225, 253, 0.52), transparent 9rem),
          linear-gradient(145deg, #22293a, #111622 58%, #0c0f17);
        padding: 24px;
        overflow: hidden;
      }

      .spotlight-visual {
        position: relative;
        display: grid;
        min-height: 330px;
        place-items: center;
      }

      .product-orb {
        position: absolute;
        border-radius: 999px;
        filter: blur(1px);
      }

      .orb-one {
        width: 210px;
        height: 210px;
        background: rgba(244, 184, 96, 0.28);
        left: 8%;
        top: 6%;
      }

      .orb-two {
        width: 180px;
        height: 180px;
        background: rgba(104, 225, 253, 0.22);
        right: 6%;
        bottom: 8%;
      }

      .bag {
        position: relative;
        display: grid;
        width: min(280px, 76%);
        aspect-ratio: 0.8;
        place-items: center;
        border: 1px solid rgba(255, 255, 255, 0.22);
        border-radius: 40px 40px 54px 54px;
        background:
          linear-gradient(145deg, rgba(255, 255, 255, 0.22), rgba(255, 255, 255, 0.03)),
          linear-gradient(135deg, #2a3144, #111622);
        box-shadow: 0 30px 80px rgba(0, 0, 0, 0.42);
        transform: rotate(-5deg);
      }

      .bag::before {
        position: absolute;
        top: -54px;
        width: 116px;
        height: 86px;
        border: 16px solid rgba(246, 247, 251, 0.22);
        border-bottom: 0;
        border-radius: 70px 70px 0 0;
        content: "";
      }

      .bag span {
        color: var(--accent);
        font-size: 5rem;
        font-weight: 900;
        letter-spacing: -0.12em;
      }

      .spotlight-details {
        display: flex;
        justify-content: space-between;
        gap: 18px;
        align-items: end;
      }

      .spotlight-details p {
        margin-bottom: 0;
        color: var(--muted);
      }

      .price {
        color: var(--text);
        font-size: 2rem;
        font-weight: 900;
        white-space: nowrap;
      }

      .section {
        padding: 54px 0;
      }

      .section-heading {
        display: flex;
        justify-content: space-between;
        gap: 18px;
        align-items: end;
        margin-bottom: 24px;
      }

      .section-heading h2 {
        margin-bottom: 0;
        font-size: clamp(2rem, 4vw, 3.4rem);
        line-height: 1;
        letter-spacing: -0.05em;
      }

      .section-heading p {
        max-width: 460px;
        margin-bottom: 0;
        color: var(--muted);
      }

      .product-grid {
        display: grid;
        grid-template-columns: repeat(4, 1fr);
        gap: 18px;
      }

      .product-card {
        border-radius: 24px;
        padding: 16px;
      }

      .product-art {
        display: grid;
        min-height: 214px;
        place-items: center;
        border-radius: 20px;
        background:
          radial-gradient(circle at 40% 25%, var(--glow), transparent 8rem),
          linear-gradient(145deg, #222838, #10141f);
        color: rgba(255, 255, 255, 0.86);
        font-size: 4rem;
      }

      .product-meta {
        display: flex;
        justify-content: space-between;
        gap: 14px;
        margin-top: 16px;
      }

      .product-card h3,
      .deal-card h3,
      .story-card h3 {
        margin-bottom: 6px;
        font-size: 1.08rem;
      }

      .product-card p,
      .deal-card p,
      .story-card p {
        margin-bottom: 0;
        color: var(--muted);
      }

      .tag {
        display: inline-flex;
        width: max-content;
        border: 1px solid var(--line);
        border-radius: 999px;
        margin-bottom: 12px;
        padding: 6px 10px;
        color: var(--accent-2);
        font-size: 0.78rem;
        font-weight: 900;
        text-transform: uppercase;
      }

      .deals-grid {
        display: grid;
        grid-template-columns: 1.1fr 0.9fr;
        gap: 18px;
      }

      .deal-card {
        display: grid;
        min-height: 320px;
        border-radius: var(--radius);
        padding: 26px;
        align-content: space-between;
        background:
          linear-gradient(135deg, rgba(244, 184, 96, 0.16), transparent 40%),
          var(--panel);
      }

      .deal-card.featured-deal {
        grid-template-columns: 1fr 0.75fr;
        gap: 18px;
        background:
          radial-gradient(circle at 78% 36%, rgba(255, 122, 144, 0.22), transparent 16rem),
          linear-gradient(135deg, rgba(104, 225, 253, 0.12), transparent 45%),
          var(--panel-strong);
      }

      .deal-value {
        color: var(--accent);
        font-size: clamp(3.8rem, 9vw, 7rem);
        font-weight: 950;
        line-height: 0.9;
        letter-spacing: -0.08em;
      }

      .deal-stack {
        display: grid;
        gap: 18px;
      }

      .mini-deal {
        min-height: 151px;
      }

      .countdown {
        display: flex;
        flex-wrap: wrap;
        gap: 10px;
        margin-top: 24px;
      }

      .time-box {
        min-width: 72px;
        border: 1px solid var(--line);
        border-radius: 16px;
        background: rgba(255, 255, 255, 0.06);
        padding: 12px;
        text-align: center;
      }

      .time-box strong {
        display: block;
        font-size: 1.35rem;
      }

      .time-box span {
        color: var(--muted);
        font-size: 0.75rem;
        font-weight: 800;
        text-transform: uppercase;
      }

      .editorial-grid {
        display: grid;
        grid-template-columns: repeat(3, 1fr);
        gap: 18px;
      }

      .story-card {
        border-radius: 24px;
        overflow: hidden;
      }

      .story-image {
        min-height: 190px;
        background:
          linear-gradient(135deg, rgba(255, 255, 255, 0.18), transparent),
          radial-gradient(circle at 70% 30%, var(--glow), transparent 8rem),
          linear-gradient(145deg, #252b3a, #111622);
      }

      .story-content {
        padding: 20px;
      }

      .story-link {
        display: inline-flex;
        margin-top: 16px;
        color: var(--accent);
        font-weight: 900;
      }

      .newsletter {
        display: grid;
        grid-template-columns: 1fr 0.9fr;
        gap: 26px;
        align-items: center;
        border-radius: var(--radius);
        margin: 54px 0 72px;
        padding: clamp(26px, 4vw, 42px);
      }

      .newsletter h2 {
        margin-bottom: 12px;
        font-size: clamp(2rem, 4vw, 3.2rem);
        line-height: 1;
        letter-spacing: -0.05em;
      }

      .newsletter p {
        margin-bottom: 0;
        color: var(--muted);
      }

      .signup-form {
        display: flex;
        gap: 10px;
      }

      .signup-form label {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip: rect(0, 0, 0, 0);
      }

      .signup-form input {
        min-width: 0;
        flex: 1;
        border: 1px solid var(--line);
        border-radius: 999px;
        background: rgba(255, 255, 255, 0.06);
        color: var(--text);
        padding: 0 18px;
      }

      .signup-form input::placeholder {
        color: #81899d;
      }

      .site-footer {
        border-top: 1px solid var(--line);
        padding: 28px 0;
        color: var(--muted);
      }

      .footer-content {
        display: flex;
        justify-content: space-between;
        gap: 18px;
      }

      @media (max-width: 960px) {
        .hero,
        .deals-grid,
        .deal-card.featured-deal,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .product-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, 1fr);
        }

        .nav-links {
          display: none;
        }
      }

      @media (max-width: 640px) {
        .container {
          width: min(100% - 22px, 1180px);
        }

        .nav {
          gap: 12px;
        }

        .brand span:last-child,
        .cart-pill span {
          display: none;
        }

        .hero {
          padding-top: 38px;
        }

        .hero-copy,
        .hero-card,
        .newsletter {
          border-radius: 22px;
        }

        .hero-stats,
        .product-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .section-heading,
        .footer-content,
        .spotlight-details,
        .product-meta,
        .signup-form {
          align-items: stretch;
          flex-direction: column;
        }

        .spotlight {
          min-height: 430px;
        }

        .signup-form .button {
          width: 100%;
        }
      }
    </style>
  </head>
  <body>
    <div class="page-shell">
      <a class="skip-link" href="#main">Skip to main content</a>
      <div id="app"></div>
    </div>

    <script>
      const products = [
        {
          name: "Astra Trail Jacket",
          category: "Outerwear",
          price: "$148",
          symbol: "◒",
          glow: "rgba(104, 225, 253, 0.34)",
        },
        {
          name: "Nocturne Carryall",
          category: "Accessories",
          price: "$96",
          symbol: "◧",
          glow: "rgba(244, 184, 96, 0.36)",
        },
        {
          name: "Meridian Knit Set",
          category: "Essentials",
          price: "$124",
          symbol: "◇",
          glow: "rgba(126, 226, 168, 0.3)",
        },
        {
          name: "Forge Runner",
          category: "Footwear",
          price: "$132",
          symbol: "◈",
          glow: "rgba(255, 122, 144, 0.3)",
        },
      ];

      const deals = [
        {
          label: "Members",
          title: "Free express shipping",
          text: "Unlock two-day delivery on every order above $75 through Sunday.",
        },
        {
          label: "Bundle",
          title: "Save 20% on layers",
          text: "Pair jackets, knits, and base tees for a smarter cold-weather kit.",
        },
      ];

      const stories = [
        {
          label: "Field Guide",
          title: "How to build a five-piece city kit",
          text: "Our editors map the versatile pieces that move from commute to dinner.",
          glow: "rgba(104, 225, 253, 0.28)",
        },
        {
          label: "Designer Notes",
          title: "The materials behind our winter drop",
          text: "Recycled insulation, brushed cotton, and low-impact dyes lead the season.",
          glow: "rgba(244, 184, 96, 0.3)",
        },
        {
          label: "Lookbook",
          title: "After-dark styling with texture",
          text: "Layer matte finishes, soft knits, and high-contrast accents with intention.",
          glow: "rgba(255, 122, 144, 0.28)",
        },
      ];

      const Header = () => `
        <header class="site-header">
          <nav class="container nav" aria-label="Main navigation">
            <a class="brand" href="#" aria-label="Northline Supply home">
              <span class="brand-mark" aria-hidden="true">N</span>
              <span>Northline Supply</span>
            </a>
            <div class="nav-links">
              <a href="#featured">Featured</a>
              <a href="#deals">Deals</a>
              <a href="#editorial">Editorial</a>
            </div>
            <div class="nav-actions">
              <button class="icon-button" type="button" aria-label="Search">⌕</button>
              <a class="cart-pill" href="#" aria-label="View cart with 2 items">Bag <span>2</span></a>
            </div>
          </nav>
        </header>
      `;

      const Hero = () => `
        <section class="container hero" aria-labelledby="hero-title">
          <div class="hero-copy">
            <p class="eyebrow">New season arrivals</p>
            <h1 id="hero-title">Retail essentials made for after dark.</h1>
            <p>
              Discover refined layers, technical accessories, and limited-run staples from
              Northline Supply's latest urban retail collection.
            </p>
            <div class="hero-actions">
              <a class="button button-primary" href="#featured">Shop featured products</a>
              <a class="button button-secondary" href="#editorial">Read the edit</a>
            </div>
            <div class="hero-stats" aria-label="Store highlights">
              <div class="stat"><strong>48h</strong><span>Express dispatch</span></div>
              <div class="stat"><strong>120+</strong><span>New arrivals</span></div>
              <div class="stat"><strong>4.9</strong><span>Average rating</span></div>
            </div>
          </div>
          <aside class="hero-card" aria-label="Featured product spotlight">
            <div class="spotlight">
              <div class="spotlight-visual" aria-hidden="true">
                <span class="product-orb orb-one"></span>
                <span class="product-orb orb-two"></span>
                <div class="bag"><span>N</span></div>
              </div>
              <div class="spotlight-details">
                <div>
                  <span class="tag">Limited drop</span>
                  <h2>Midnight Capsule</h2>
                  <p>Eight pieces designed for cold commutes, late checkouts, and weekend escapes.</p>
                </div>
                <div class="price">$88+</div>
              </div>
            </div>
          </aside>
        </section>
      `;

      const ProductCard = (product) => `
        <article class="product-card">
          <div class="product-art" style="--glow: ${product.glow}" aria-hidden="true">${product.symbol}</div>
          <div class="product-meta">
            <div>
              <span class="tag">${product.category}</span>
              <h3>${product.name}</h3>
              <p>Premium construction with everyday utility.</p>
            </div>
            <strong class="price">${product.price}</strong>
          </div>
        </article>
      `;

      const FeaturedProducts = () => `
        <section class="container section" id="featured" aria-labelledby="featured-title">
          <div class="section-heading">
            <h2 id="featured-title">Featured products</h2>
            <p>Curated bestsellers and new arrivals with tactile materials, clean silhouettes, and durable finishes.</p>
          </div>
          <div class="product-grid">
            ${products.map(ProductCard).join("")}
          </div>
        </section>
      `;

      const Deals = () => `
        <section class="container section" id="deals" aria-labelledby="deals-title">
          <div class="section-heading">
            <h2 id="deals-title">Deals worth staying up for</h2>
            <p>Short-run promotions for shoppers building a smarter seasonal wardrobe.</p>
          </div>
          <div class="deals-grid">
            <article class="deal-card featured-deal">
              <div>
                <span class="tag">Flash event</span>
                <h3>Dark Week private sale</h3>
                <p>Take up to 35% off select outerwear, bags, and footwear before the collection rotates.</p>
                <div class="countdown" aria-label="Sale countdown">
                  <div class="time-box"><strong>02</strong><span>Days</span></div>
                  <div class="time-box"><strong>14</strong><span>Hours</span></div>
                  <div class="time-box"><strong>39</strong><span>Minutes</span></div>
                </div>
              </div>
              <div class="deal-value">35%<br />off</div>
            </article>
            <div class="deal-stack">
              ${deals
                .map(
                  (deal) => `
                    <article class="deal-card mini-deal">
                      <div>
                        <span class="tag">${deal.label}</span>
                        <h3>${deal.title}</h3>
                        <p>${deal.text}</p>
                      </div>
                    </article>
                  `
                )
                .join("")}
            </div>
          </div>
        </section>
      `;

      const Editorial = () => `
        <section class="container section" id="editorial" aria-labelledby="editorial-title">
          <div class="section-heading">
            <h2 id="editorial-title">From the editorial desk</h2>
            <p>Buying guides, design stories, and styling ideas from the people shaping each collection.</p>
          </div>
          <div class="editorial-grid">
            ${stories
              .map(
                (story) => `
                  <article class="story-card">
                    <div class="story-image" style="--glow: ${story.glow}" aria-hidden="true"></div>
                    <div class="story-content">
                      <span class="tag">${story.label}</span>
                      <h3>${story.title}</h3>
                      <p>${story.text}</p>
                      <a class="story-link" href="#">Read story</a>
                    </div>
                  </article>
                `
              )
              .join("")}
          </div>
        </section>
      `;

      const Newsletter = () => `
        <section class="container newsletter" aria-labelledby="newsletter-title">
          <div>
            <p class="eyebrow">Early access</p>
            <h2 id="newsletter-title">Get first pick of drops, edits, and private deals.</h2>
            <p>Join the Northline list for launch alerts and member-only retail events.</p>
          </div>
